import { Injectable } from "@angular/core";
import { HttpClient } from "@angular/common/http";
import { Observable } from "rxjs/Rx";
import { environment } from "src/environments/environment";

@Injectable()
export class DataService {
  private cache: any = {};
  private emisApiUrlJango1: string = environment.emisApiUrlJango1;

  constructor(private http: HttpClient) {}

  getData(route, refresh) {
    if (this.dataForRouteIsCached(route, refresh)) {
      return Observable.of(this.cache[route]);
    } else {
      return this.http.get<any>(route).map((response) => {
        this.cache[route] = response;
        return response;
      });
    }
  }

  getDataWithParamsFiles(route, params, refresh) {
    if (this.dataForRouteIsCached(route, refresh)) {
      return Observable.of(this.cache[route]);
    } else {
      // no cached data or refresh requested
      return this.http.get<any>(route, { params: params }).map((response) => {
        this.cache[route] = response;
        return response;
      });
    }
  }

  post(route, data) {
    return this.http.post<any>(route, data).map((response) => {
      this.cache[route] = response;
      return response;
    });
  }

  getRecord(route) {
    return this.http.get<any>(route);
  }

  getDataWithParams(route, params, refresh) {
    if (this.dataForRouteIsCached(route, refresh)) {
      return Observable.of(this.cache[route]);
    } else {
      return this.http.get<any>(route, { params: params }).map((response) => {
        this.cache[route] = response;
        return response;
      });
    }
  }

  dataForRouteIsCached(route, refresh) {
    return this.cache[route] && (refresh === false || refresh === undefined);
  }

  clearCache() {
    this.cache = {};
  }

  clearRouteCache(route) {
    this.cache[route] = null;
  }

  put(route, data) {
    return this.http.put<any>(route, data);
  }

  getFileWithParams(route, params, refresh) {
    if (this.dataForRouteIsCached(route, refresh)) {
      return Observable.of(this.cache[route]);
    } else {
      // no cached data or refresh requested
      return this.http.get<any>(route, { params: params }).map((response) => {
        this.cache[route] = response;
        return response;
      });
    }
  }
  getDJangoData(endpoint: string, refresh?: boolean) {
    const url = `${this.emisApiUrlJango1}${endpoint}`;

    if (this.dataForRouteIsCached(url, refresh)) {
      return Observable.of(this.cache[url]);
    } else {
      return this.http.get<any>(url).map((response) => {
        this.cache[url] = response;
        return response;
      });
    }
  }
  postDJangoData(endpoint: string, data: any) {
    const url = `${this.emisApiUrlJango1}${endpoint}`;

    return this.http.post<any>(url, data).map((response) => {
      this.cache[url] = response;
      return response;
    });
  }
}
