import "rxjs/add/operator/catch";
import "rxjs/add/observable/throw";
import { environment } from "../../environments/environment";
import { Observable } from "rxjs";
import { AlertService } from "./alert.service";
import { UserSessionService } from "./usersession.service";
import { AuthenticationService } from "./authentication.service";
import { NavController } from "@ionic/angular";
import { Network } from "@ionic-native/network/ngx";
import { Injectable } from "@angular/core";
import {
  HttpEvent,
  HttpInterceptor,
  HttpHandler,
  HttpRequest,
  HttpErrorResponse,
} from "@angular/common/http";
import "rxjs/add/observable/throw";
import "rxjs/add/operator/catch";
import { throwError } from "rxjs";
@Injectable()
export class HttpInterceptorService implements HttpInterceptor {
  mod: any;

  constructor(
    public alertService: AlertService,
    public userSessionService: UserSessionService,
    private authService: AuthenticationService,
    public navCtrl: NavController,
    private network: Network,
  ) {}

  intercept(
    request: HttpRequest<any>,
    next: HttpHandler,
  ): Observable<HttpEvent<any>> {
    const authToken = window.localStorage.getItem("user_token");
    let authReq;

    if (request.url.startsWith(environment.loginUrl)) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          "Content-Type": "application/json",
          Authorization: "EMIS@2019_api",
        },
      });
    } else if (
      request.url.startsWith(environment.awsApiUrl) &&
      authToken !== null
    ) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          Connection: "keep-alive",
          "x-api-key": "3dPWrCiAyS96cjq8HFf21XLjEkFnOgU9mJVZUla7",
          "Content-Type": "application/json",
        },
      });
    } else if (
      request.url.startsWith(environment.emisApiUrl || environment.api_url) &&
      authToken !== null
    ) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          Token: authToken,
          "Content-Type": "application/json",
          Authorization: "EMIS_web@2019_api",
        },
      });
    } else if (request.url.startsWith("https://emis3.tnschools.gov.in/api")) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          Token: authToken,
          "Content-Type": "application/json",
          Authorization: "EMIS_web@2019_api",
        },
      });
    } else if (request.url.startsWith(environment.emisApiUrl3)) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          Token: authToken,
          "Content-Type": "application/json",
          Authorization: "EMIS_web@2019_api",
        }, //EMIS@2019_api
      });
    } else if (
      request.url.startsWith(environment.tntpApiUrl) &&
      authToken !== null
    ) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          Token: authToken,
          Authorization: "2fca342e66efb1568d1d28edc7e59c64",
          "Content-Type": "application/json",
        },
      });
    } else if (
      request.url.startsWith(environment.emisApiUrlJango1) &&
      authToken !== null
    ) {
      authReq = request.clone({
        url: request.url,
        setHeaders: {
          Token: authToken,
          "Content-Type": "application/json",
          Authorization: "EMIS_web@2019_api",
        },
      });
    } else {
      authReq = request.clone({
        url: request.url,
        setHeaders: { "Content-Type": "" },
      });
    }
    return next.handle(authReq).catch((error, caught) => {
      if (error instanceof HttpErrorResponse) {
        if (error.status === 401) {
          this.authService.appLogout();
        } else {
          this.broadcastFriendlyErrorMessage(error);
        }
      }
      return Observable.throwError(error);
    }) as any;
  }

  private handleError<T>(operation = "operation", result?: T) {
    return (error: any): Observable<T> => {
      if (error instanceof HttpErrorResponse) {
        if (error.status == 401) {
          // localStorage.clear();
          // this.authService.logOut();
          // this.router.navigate(['/login']);
        } else if (error.status == 404) {
          this.alertService.error(error.message);
        } else if (error.status == 503) {
          this.alertService.error(error.message);
        } else if (error.status === 500) {
          if (error.message) {
            this.alertService.error(error.message);
          }
        } else {
          let errorMessage = "";
          let type: number;
          if (error.error instanceof ErrorEvent) {
            // client-side error
            errorMessage = `${error.error.message}`;
            type = 1;
          } else {
            // server-side error
            errorMessage = `${error.message}`;
            type = 2;
          }
          // this.alertService.error((type == 2) ? `${error.status} / ${error.statusText} Occurred` : `Error Message : ${errorMessage}`);
          return throwError(
            "An error occurred, please try again later \n " + errorMessage,
          );
        }
      }
    };
  }

  broadcastFriendlyErrorMessage(rejection) {
    this.mod = this.userSessionService.mod1();

    let msg = "";
    if (
      rejection.status === 0 &&
      (rejection.statusText === "" || rejection.statusText === "Unknown Error")
    ) {
      if (this.mod != 23) {
        if (this.network.type === "none") {
          this.alertService.error(
            "No network connection. Please Connect to the Internet",
          );
        } else {
          this.alertService.error(
            "Unable to connect to the server, please try again in a couple of seconds.",
          );
        }
      }
    } else if (rejection.status === 400) {
      if (
        rejection.error &&
        (rejection.error.error || rejection.error.error_description)
      ) {
        msg = rejection.error.error_description;
      } else if (rejection.error) {
        msg = rejection.error;
      }
      this.alertService.error(msg);
    } else if (rejection.status === 404) {
      if (rejection.message) {
        this.alertService.error(rejection.message);
      }
    } else if (rejection.status === 500) {
      if (rejection.message) {
        let ex = rejection.message;
        while (ex.innerException) {
          ex = ex.innerException;
        }
        this.alertService.error(ex.exceptionMessage);
      }
    } else if (rejection.responseStatus === 401) {
      this.authService.appLogout();
    } else if (rejection.responseStatus === 0) {
      this.alertService.error("Error occured, while uploading file");
    } else if (rejection.responseStatus === 400) {
      if (rejection.response) {
        msg = rejection.response;
      }
      this.alertService.error(msg);
    }
  }
}
