  postParse(list, neededCols) {
    let temp = [];
    for (var i = 0; i < list.length; i++) {
      let data = list.item(i);
      // console.log(data,data.isPost);
      if (data.isPost == 2) {
        let obj = {};
        neededCols.forEach((cols) => {
          obj[cols] = data[cols];
        });
        temp.push(obj);
      }
    }
    return temp;
  }

