  parseScreenQues(list) {
    let temp = [];
    for (var i = 0; i < list.length; i++) {
      temp.push(list.item(i));
    }
    let stdIds = [
      ...new Map(temp.map((item) => [item["StuId"], item])).values(),
    ];
    let finalVal = [];
    let newDate = moment(new Date()).format("YYYY-MM-DD");

    for (let i = 0; i < stdIds.length; i++) {
      let screnAns = temp.filter((obj) => {
        return obj.StuId == stdIds[i].StuId;
      });
      let ans = [];
      screnAns.filter((obj) => {
        let obj1 = {};
        ["IndxID", "Qid", "ResChar", "isactive"].forEach((cols) => {
          obj1[cols] = obj[cols];
        });
        ans.push(obj1);
      });
      let stdDetsils = {
        IndxID: null,
        SchlId: screnAns[0].school_key_id,
        ScrenDate: newDate,
        Status: 1,
        StuId: screnAns[0].StuId,
        Refer:
          screnAns[0].refer_to == "false" || !screnAns[0].refer_to
            ? ""
            : screnAns[0].refer_to,
        userName: this.userSessionService.emis_username(),
        disabiTypes: screnAns[0].disabi_types,
        CwsnScreeningDetails: ans,
      };
      finalVal.push(stdDetsils);
    }
    return finalVal;
  }

  async loadHealthRes(schId) {
    let query =
      "SELECT * FROM health_screen_ques" +
      ' WHERE school_key_id = "' +
      schId +
      '"';
    debugger;
    await this.sqliteDB.update(query).then((res) => {
      if (!(res.rows.length > 0)) {
        let health_refer_res =
          "https://d1wpyxz35bzzz4.cloudfront.net/health_json/student_refer_health_cwsn_schl_wise_" +
          schId +
          ".json";
        this.http.get<any>(health_refer_res).subscribe((res2) => {
          let sqlArray: any = [];
          res2.forEach((element) => {
            sqlArray.push([
              "INSERT INTO health_screen_ques VALUES (?,?,?,?,?,?)",
              [null, schId, element.StuId, element.Qid, element.ResChar, 1],
            ]);
          });
          this.sqliteDB.bulkInsert(sqlArray).then((insertres) => {});
        });
      }
    });
  }

